 13	/// XML 1.0 Fifth Edition `Char` production.
 14	pub const fn is_xml_char(cp: u32) -> bool {
 15	    cp == 0x9
 16	        || cp == 0xa
 17	        || cp == 0xd
 18	        || (cp >= 0x20 && cp <= 0xd7ff)
 19	        || (cp >= 0xe000 && cp <= 0xfffd)
 20	        || (cp >= 0x10000 && cp <= 0x10ffff)
 21	}
 22	
 23	/// Decodes one strict UTF-8 scalar at `position` and returns it with the next
 24	/// byte offset. On failure, callers retain their original position.
 25	pub fn utf8_next(bytes: &[u8], position: usize) -> Option<(u32, usize)> {
 26	    let first = *bytes.get(position)?;
 27	    let (count, mut value) = match first {
 28	        0x00..=0x7f => (1usize, u32::from(first)),
 29	        0xc2..=0xdf => (2, u32::from(first & 0x1f)),
 30	        0xe0..=0xef => (3, u32::from(first & 0x0f)),
 31	        0xf0..=0xf4 => (4, u32::from(first & 0x07)),
 32	        _ => return None,
 33	    };
 34	    let end = position.checked_add(count)?;
 35	    let tail = bytes.get(position + 1..end)?;
 36	    for &byte in tail {
 37	        if byte & 0xc0 != 0x80 {
 38	            return None;
 39	        }
 40	        value = (value << 6) | u32::from(byte & 0x3f);
 41	    }
 42	    let second = *tail.first().unwrap_or(&0);
 43	    if (count == 3 && ((first == 0xe0 && second < 0xa0) || (first == 0xed && second >= 0xa0)))
 44	        || (count == 4 && ((first == 0xf0 && second < 0x90) || (first == 0xf4 && second >= 0x90)))
 45	        || value > 0x10ffff
 46	        || (0xd800..=0xdfff).contains(&value)
 47	    {
 48	        return None;
 49	    }
 50	    Some((value, end))
 51	}
