 53	/// XML 1.0 Fifth Edition `NameStartChar` production.
 54	pub const fn is_name_start(cp: u32) -> bool {
 55	    cp == 0x3a
 56	        || cp == 0x5f
 57	        || (cp >= 0x41 && cp <= 0x5a)
 58	        || (cp >= 0x61 && cp <= 0x7a)
 59	        || (cp >= 0xc0 && cp <= 0xd6)
 60	        || (cp >= 0xd8 && cp <= 0xf6)
 61	        || (cp >= 0xf8 && cp <= 0x2ff)
 62	        || (cp >= 0x370 && cp <= 0x37d)
 63	        || (cp >= 0x37f && cp <= 0x1fff)
 64	        || (cp >= 0x200c && cp <= 0x200d)
 65	        || (cp >= 0x2070 && cp <= 0x218f)
 66	        || (cp >= 0x2c00 && cp <= 0x2fef)
 67	        || (cp >= 0x3001 && cp <= 0xd7ff)
 68	        || (cp >= 0xf900 && cp <= 0xfdcf)
 69	        || (cp >= 0xfdf0 && cp <= 0xfffd)
 70	        || (cp >= 0x10000 && cp <= 0xeffff)
 71	}
 72	
 73	/// XML 1.0 Fifth Edition `NameChar` production.
 74	pub const fn is_name_char(cp: u32) -> bool {
 75	    is_name_start(cp)
 76	        || cp == 0x2d
 77	        || cp == 0x2e
 78	        || (cp >= 0x30 && cp <= 0x39)
 79	        || cp == 0xb7
 80	        || (cp >= 0x300 && cp <= 0x36f)
 81	        || (cp >= 0x203f && cp <= 0x2040)
 82	}
