 84	/// XML whitespace is exactly space, tab, line feed, and carriage return.
 85	pub const fn is_xml_whitespace(byte: u8) -> bool {
 86	    matches!(byte, 0x20 | 0x09 | 0x0a | 0x0d)
 87	}
