137	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
138	enum DoctypePhase { Start, Main, Quote, Subset, SubsetQuote, Lt, Bang, BangDash, Comment, Pi }
139	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
140	enum DoctypeResult { More, Done, Bad }
