142	#[derive(Debug, Clone, Copy)]
143	struct DoctypeState {
144	    phase: DoctypePhase,
145	    quote: u8,
146	    run: u8,
147	    subset_closed: bool,
148	}
149	
150	impl Default for DoctypeState {
151	    fn default() -> Self {
152	        Self { phase: DoctypePhase::Start, quote: 0, run: 0, subset_closed: false }
153	    }
154	}
155	
156	impl DoctypeState {
157	    fn step(&mut self, byte: u8) -> DoctypeResult {
158	        loop {
159	            match self.phase {
160	                DoctypePhase::Start => {
161	                    if !is_xml_whitespace(byte) { return DoctypeResult::Bad; }
162	                    self.phase = DoctypePhase::Main;
163	                    return DoctypeResult::More;
164	                }
165	                DoctypePhase::Main => match byte {
166	                    b'"' | b'\'' => { self.quote = byte; self.phase = DoctypePhase::Quote; }
167	                    b'[' => {
168	                        if self.subset_closed { return DoctypeResult::Bad; }
169	                        self.phase = DoctypePhase::Subset;
170	                    }
171	                    b'>' => return DoctypeResult::Done,
172	                    b'<' => return DoctypeResult::Bad,
173	                    _ => {}
174	                },
175	                DoctypePhase::Quote => if byte == self.quote { self.phase = DoctypePhase::Main; },
176	                DoctypePhase::Subset => match byte {
177	                    b'"' | b'\'' => { self.quote = byte; self.phase = DoctypePhase::SubsetQuote; }
178	                    b'<' => self.phase = DoctypePhase::Lt,
179	                    b']' => { self.subset_closed = true; self.phase = DoctypePhase::Main; }
180	                    _ => {}
181	                },
182	                DoctypePhase::SubsetQuote => if byte == self.quote { self.phase = DoctypePhase::Subset; },
183	                DoctypePhase::Lt => match byte {
184	                    b'!' => { self.phase = DoctypePhase::Bang; return DoctypeResult::More; }
185	                    b'?' => { self.run = 0; self.phase = DoctypePhase::Pi; return DoctypeResult::More; }
186	                    _ => { self.phase = DoctypePhase::Subset; continue; }
187	                },
188	                DoctypePhase::Bang => if byte == b'-' { self.phase = DoctypePhase::BangDash; return DoctypeResult::More; } else { self.phase = DoctypePhase::Subset; continue; },
189	                DoctypePhase::BangDash => if byte == b'-' { self.run = 0; self.phase = DoctypePhase::Comment; return DoctypeResult::More; } else { self.phase = DoctypePhase::Subset; continue; },
190	                DoctypePhase::Comment => {
191	                    if byte == b'-' { self.run = self.run.saturating_add(1).min(2); }
192	                    else if byte == b'>' && self.run >= 2 { self.phase = DoctypePhase::Subset; }
193	                    else { self.run = 0; }
194	                }
195	                DoctypePhase::Pi => {
196	                    if byte == b'>' && self.run == 1 { self.phase = DoctypePhase::Subset; }
197	                    else { self.run = u8::from(byte == b'?'); }
198	                }
199	            }
200	            return DoctypeResult::More;
201	        }
202	    }
203	}
