205	/// Borrowing scanner. Source bytes remain immutable and are never normalized.
206	pub struct XmlReader<'a> {
207	    source: &'a [u8],
208	    bytes_read: usize,
209	    token_start: usize,
210	    name_offset: usize,
211	    name_length: usize,
212	    attribute_count: usize,
213	    probe_position: usize,
214	    mode: Mode,
215	    probe: Probe,
216	    closing: bool,
217	    name_complete: bool,
218	    in_quote: bool,
219	    pending_slash: bool,
220	    self_closing: bool,
221	    quote: u8,
222	    complete: bool,
223	    element_seen: bool,
224	    doctype_seen: bool,
225	    doctype: DoctypeState,
226	    diagnostic: Diagnostic,
227	}
228	
229	impl<'a> XmlReader<'a> {
230	    /// Starts a reader borrowing `source` until this reader is dropped.
231	    pub fn new(source: &'a [u8]) -> Result<Self, ReaderStatus> {
232	        if source.len() > MAX_READER_SOURCE_BYTES { return Err(ReaderStatus::Limit); }
233	        Ok(Self {
234	            source, bytes_read: 0, token_start: 0, name_offset: 0, name_length: 0,
235	            attribute_count: 0, probe_position: 0, mode: Mode::Text, probe: Probe::None,
236	            closing: false, name_complete: false, in_quote: false, pending_slash: false,
237	            self_closing: false, quote: 0, complete: false, element_seen: false,
238	            doctype_seen: false, doctype: DoctypeState::default(), diagnostic: Diagnostic::clear(),
239	        })
240	    }
241	
242	    /// Advances by at most `byte_budget` bytes, capped at 64 KiB, and emits
243	    /// complete lexical tags. Returning false from the callback is an error.
244	    pub fn step<F>(&mut self, byte_budget: usize, mut on_tag: F) -> ReaderStatus
245	    where F: FnMut(ReaderTag) -> bool {
246	        if byte_budget == 0 { return ReaderStatus::Invalid; }
247	        if self.diagnostic.category != XmlError::None { return ReaderStatus::Malformed; }
248	        if self.complete { return ReaderStatus::Complete; }
249	        let budget = byte_budget.min(MAX_READER_STEP_BYTES);
250	        let end = self.bytes_read.saturating_add(budget).min(self.source.len());
251	        while self.bytes_read < end && self.diagnostic.category == XmlError::None {
252	            let at = self.bytes_read;
253	            let byte = self.source[at];
254	            match self.mode {
255	                Mode::Text => if byte == b'<' {
256	                    self.mode = Mode::Probe;
257	                    self.token_start = at;
258	                    self.probe = Probe::None;
259	                    self.probe_position = 0;
260	                },
261	                Mode::Probe => self.scan_probe(byte, at),
262	                Mode::Tag => {
263	                    if !self.name_complete {
264	                        if is_reader_name_byte(byte) {
265	                            if self.name_length == MAX_READER_NAME_BYTES { self.fail(XmlError::InvalidName, self.name_offset); }
266	                            else { self.name_length += 1; }
267	                            self.bytes_read += 1;
268	                            continue;
269	                        }
270	                        if self.name_length == 0 { self.fail(XmlError::InvalidName, self.name_offset); }
271	                        else { self.name_complete = true; }
272	                    }
273	                    if self.in_quote {
274	                        if byte == self.quote { self.in_quote = false; }
275	                    } else if byte == b'\'' || byte == b'"' {
276	                        self.in_quote = true;
277	                        self.quote = byte;
278	                        self.attribute_count = self.attribute_count.saturating_add(1);
279	                    } else if byte == b'/' { self.pending_slash = true; }
280	                    else if byte == b'>' {
281	                        self.self_closing = self.pending_slash;
282	                        if !self.emit_tag(at + 1, &mut on_tag) { break; }
283	                    } else { self.pending_slash = false; }
284	                }
285	                Mode::Comment if byte == b'>' && at >= 2 && &self.source[at - 2..at] == b"--" => self.mode = Mode::Text,
286	                Mode::Cdata if byte == b'>' && at >= 2 && &self.source[at - 2..at] == b"]]" => self.mode = Mode::Text,
287	                Mode::Doctype => match self.doctype.step(byte) {
288	                    DoctypeResult::Bad => self.fail(XmlError::MalformedSyntax, at),
289	                    DoctypeResult::Done => self.mode = Mode::Text,
290	                    DoctypeResult::More => {}
291	                },
292	                Mode::Pi if byte == b'>' && at > 0 && self.source[at - 1] == b'?' => self.mode = Mode::Text,
293	                _ => {}
294	            }
295	            self.bytes_read += 1;
296	        }
297	        if self.diagnostic.category != XmlError::None { return ReaderStatus::Malformed; }
298	        if self.bytes_read == self.source.len() {
299	            if self.mode != Mode::Text { self.fail(XmlError::IncompleteDocument, self.source.len()); }
300	            else { self.complete = true; }
301	        }
302	        if self.diagnostic.category == XmlError::None {
303	            if self.complete { ReaderStatus::Complete } else { ReaderStatus::Ok }
304	        } else { ReaderStatus::Malformed }
305	    }
306	
307	    pub fn progress(&self) -> ReaderProgress {
308	        ReaderProgress { bytes_read: self.bytes_read, source_bytes: self.source.len(), diagnostic: self.diagnostic, complete: self.complete }
309	    }
310	
311	    fn scan_probe(&mut self, byte: u8, at: usize) {
312	        if self.probe_position == 0 {
313	            if byte == b'?' { self.mode = Mode::Pi; }
314	            else if byte == b'/' {
315	                self.begin_tag(true, at + 1);
316	            } else if byte == b'!' { self.probe_position = 1; }
317	            else if is_reader_name_byte(byte) {
318	                self.begin_tag(false, at);
319	                self.name_length = 1;
320	            } else { self.fail(XmlError::InvalidName, at); }
321	        } else if self.probe == Probe::None {
322	            if byte == b'-' { self.probe = Probe::Comment; self.probe_position = 1; }
323	            else if byte == b'[' { self.probe = Probe::Cdata; self.probe_position = 1; }
324	            else if byte == b'D' && !self.doctype_seen && !self.element_seen {
325	                self.probe = Probe::Doctype;
326	                self.probe_position = 1;
327	            } else { self.fail(XmlError::UnsupportedDtd, self.token_start); }
328	        } else if self.probe == Probe::Comment {
329	            if byte != b'-' { self.fail(XmlError::MalformedSyntax, self.token_start); }
330	            else { self.mode = Mode::Comment; }
331	        } else if self.probe == Probe::Doctype {
332	            const TAIL: &[u8] = b"OCTYPE";
333	            let index = self.probe_position - 1;
334	            if TAIL.get(index).copied() != Some(byte) { self.fail(XmlError::UnsupportedDtd, self.token_start); }
335	            else if self.probe_position == TAIL.len() {
336	                self.mode = Mode::Doctype;
337	                self.doctype_seen = true;
338	                self.doctype = DoctypeState::default();
339	            } else { self.probe_position += 1; }
340	        } else {
341	            const TAIL: &[u8] = b"CDATA[";
342	            let index = self.probe_position - 1;
343	            if index >= TAIL.len() || TAIL[index] != byte { self.fail(XmlError::MalformedSyntax, self.token_start); }
344	            else if self.probe_position == TAIL.len() { self.mode = Mode::Cdata; }
345	            else { self.probe_position += 1; }
346	        }
347	    }
348	
349	    fn begin_tag(&mut self, closing: bool, name_offset: usize) {
350	        self.mode = Mode::Tag;
351	        self.closing = closing;
352	        self.name_offset = name_offset;
353	        self.name_length = 0;
354	        self.attribute_count = 0;
355	        self.name_complete = false;
356	        self.pending_slash = false;
357	    }
358	
359	    fn emit_tag<F>(&mut self, end: usize, callback: &mut F) -> bool
360	    where F: FnMut(ReaderTag) -> bool {
361	        if self.name_length == 0 || self.name_length > MAX_READER_NAME_BYTES {
362	            self.fail(XmlError::InvalidName, self.name_offset);
363	            return false;
364	        }
365	        if !self.closing { self.element_seen = true; }
366	        let kind = if self.closing { TagKind::EndElement } else if self.self_closing { TagKind::EmptyElement } else { TagKind::StartElement };
367	        let tag = ReaderTag {
368	            kind,
369	            source: Span { start: self.token_start, end },
370	            name: Span { start: self.name_offset, end: self.name_offset + self.name_length },
371	            attribute_count: self.attribute_count,
372	        };
373	        if !callback(tag) {
374	            self.fail(XmlError::OutputExhausted, self.token_start);
375	            return false;
376	        }
377	        self.mode = Mode::Text;
378	        true
379	    }
380	
381	    fn fail(&mut self, category: XmlError, offset: usize) {
382	        if self.diagnostic.category == XmlError::None {
383	            self.diagnostic = Diagnostic { category, offset: offset.min(self.source.len()) };
384	        }
385	    }
386	}
387	
388	fn is_reader_name_byte(byte: u8) -> bool {
389	    byte.is_ascii_alphanumeric() || byte >= 0x80 || matches!(byte, b'_' | b'-' | b'.' | b':')
390	}
