213	        match key { b"version" if !version&&!encoding&&!standalone&&value==b"1.0"=>version=true,
214	            b"encoding" if version&&!encoding&&!standalone&&!value.is_empty()&&value[0].is_ascii_alphabetic()=>{if !value.iter().all(|c|c.is_ascii_alphanumeric()||matches!(c,b'.'|b'_'|b'-')){return Err(Fault(XmlError::MalformedSyntax,vs))}if !value.eq_ignore_ascii_case(b"utf-8"){return Err(Fault(XmlError::UnsupportedEncoding,vs))}encoding=true},
