221	pub fn tokenize(source: &[u8], mut limits: XmlLimits) -> (Vec<XmlToken>, XmlResult) { tokenize_impl(source, &mut limits, MAX_INPUT_BYTES, usize::MAX) }
222	pub fn tokenize_large(source: &[u8]) -> (Vec<XmlToken>, XmlResult) { tokenize_impl(source, &mut XmlLimits { input_bytes: MAX_LARGE_INPUT_BYTES, ..XmlLimits::default() }, MAX_LARGE_INPUT_BYTES, usize::MAX) }
223	pub fn tokenize_with_capacity(source: &[u8], limits: XmlLimits, token_capacity: usize) -> (Vec<XmlToken>, XmlResult) { tokenize_impl(source, &mut limits.clone(), MAX_INPUT_BYTES, token_capacity) }
224	pub fn tokenize_large_with_capacity(source: &[u8], token_capacity: usize) -> (Vec<XmlToken>, XmlResult) {
