227	pub fn tokenize_cancelable<F: FnMut() -> bool>(source: &[u8], limits: XmlLimits, token_capacity: usize, mut canceled: F) -> (Vec<XmlToken>, XmlResult, StreamStatus) {
228	    if canceled() { return (Vec::new(), XmlResult::default(), StreamStatus::Canceled); }
229	    for _chunk in source.chunks(64 * 1024) {
230	        if canceled() { return (Vec::new(), XmlResult::default(), StreamStatus::Canceled); }
231	    }
232	    let (tokens, result) = tokenize_with_capacity(source, limits, token_capacity);
233	    if result.diagnostic.category != XmlError::None { return (tokens, result, StreamStatus::Failed); }
234	    if canceled() { return (Vec::new(), XmlResult::default(), StreamStatus::Canceled); }
235	    (tokens, result, StreamStatus::Complete)
236	}
