210	fn validate_declaration(src: &[u8], span: XmlSpan) -> Result<(), Fault> {
211	    let end=span.end().unwrap_or(src.len());let mut p=span.offset;let(mut version,mut encoding,mut standalone)=(false,false,false);
212	    while p<end { while p<end&&is_xml_whitespace(src[p]){p+=1} if p==end{break} let ns=p;while p<end&&src[p].is_ascii_alphabetic(){p+=1}let key=&src[ns..p];while p<end&&is_xml_whitespace(src[p]){p+=1}if p>=end||src[p]!=b'='{return Err(Fault(XmlError::MalformedSyntax,p))}p+=1;while p<end&&is_xml_whitespace(src[p]){p+=1}if p>=end||!matches!(src[p],b'\''|b'"'){return Err(Fault(XmlError::MalformedSyntax,p))}let q=src[p];p+=1;let vs=p;while p<end&&src[p]!=q{p+=1}if p>=end{return Err(Fault(XmlError::MalformedSyntax,vs-1))}let value=&src[vs..p];p+=1;if p<end&&!is_xml_whitespace(src[p]){return Err(Fault(XmlError::MalformedSyntax,p))}
213	        match key { b"version" if !version&&!encoding&&!standalone&&value==b"1.0"=>version=true,
214	            b"encoding" if version&&!encoding&&!standalone&&!value.is_empty()&&value[0].is_ascii_alphabetic()=>{if !value.iter().all(|c|c.is_ascii_alphanumeric()||matches!(c,b'.'|b'_'|b'-')){return Err(Fault(XmlError::MalformedSyntax,vs))}if !value.eq_ignore_ascii_case(b"utf-8"){return Err(Fault(XmlError::UnsupportedEncoding,vs))}encoding=true},
215	            b"standalone" if version&&!standalone&&matches!(value,b"yes"|b"no")=>standalone=true,
216	            _=>return Err(Fault(XmlError::MalformedSyntax,ns)) }
217	    }
218	    if !version{return Err(Fault(XmlError::MalformedSyntax,span.offset))}Ok(())
219	}
