231	    }
232	    let (tokens, result) = tokenize_with_capacity(source, limits, token_capacity);
233	    if result.diagnostic.category != XmlError::None { return (tokens, result, StreamStatus::Failed); }
234	    if canceled() { return (Vec::new(), XmlResult::default(), StreamStatus::Canceled); }
