238	    if canceled(){return (Vec::new(),XmlResult::default(),StreamStatus::Canceled)}
239	    for _chunk in source.chunks(64*1024){if canceled(){return (Vec::new(),XmlResult::default(),StreamStatus::Canceled)}}
240	    let (tokens,result)=tokenize_large_with_capacity(source,token_capacity);
241	    if result.diagnostic.category!=XmlError::None{return (tokens,result,StreamStatus::Failed)}
242	    if canceled(){return (Vec::new(),XmlResult::default(),StreamStatus::Canceled)}(tokens,result,StreamStatus::Complete)
