244	fn tokenize_impl(source:&[u8],limits:&mut XmlLimits,hard:usize,token_capacity:usize)->(Vec<XmlToken>,XmlResult){
245	    limits.input_bytes=limits.input_bytes.min(hard);limits.nesting_depth=limits.nesting_depth.min(MAX_DEPTH);limits.nodes=limits.nodes.min(MAX_NODES);limits.attributes_per_element=limits.attributes_per_element.min(MAX_ATTRIBUTES_PER_ELEMENT);limits.total_attributes=limits.total_attributes.min(MAX_TOTAL_ATTRIBUTES);limits.text_run_bytes=limits.text_run_bytes.min(MAX_TEXT_RUN_BYTES);
246	    if source.len()>limits.input_bytes { return (Vec::new(),XmlResult{diagnostic:XmlDiagnostic{category:XmlError::InputLimit,offset:limits.input_bytes},..XmlResult::default()}); }
247	    let parser=Parser{src:source,pos:0,depth:0,roots:0,attrs:0,limits:*limits,tokens:Vec::new(),result:XmlResult::default(),open_names:Vec::new(),token_capacity};
248	    match parser.run(){Ok((tokens,result))=>(tokens,result),Err(Fault(category,offset))=>(Vec::new(),XmlResult{diagnostic:XmlDiagnostic{category,offset},..XmlResult::default()})}
249	}
