252	pub enum StreamStatus { Ok, Complete, Failed, Canceled }
253	pub struct XmlTokenStream<'a> { source:&'a [u8], budgeted:usize, parse_frontier:usize, visible:usize, visit_index:usize,
254	    parsed:bool, finished:bool, canceled:bool, taken:bool, result:XmlResult, tokens:Vec<XmlToken>, storage_limit:usize }
255	impl<'a> XmlTokenStream<'a> {
256	    pub fn new(source:&'a [u8],storage_limit:usize)->Result<Self,StreamStatus>{if source.len()>MAX_LARGE_INPUT_BYTES||storage_limit<size_of::<XmlToken>(){return Err(StreamStatus::Failed)}Ok(Self{source,budgeted:0,parse_frontier:0,visible:0,visit_index:0,parsed:false,finished:false,canceled:false,taken:false,result:XmlResult::default(),tokens:Vec::new(),storage_limit})}
257	    pub fn step(&mut self,budget:usize,canceled:bool) -> StreamStatus {
258	        if self.canceled{return StreamStatus::Canceled} if self.result.diagnostic.category!=XmlError::None{return StreamStatus::Failed} if budget==0{return StreamStatus::Failed} if canceled{self.canceled=true;return StreamStatus::Canceled} if self.finished{return StreamStatus::Complete}
259	        let budget=budget.min(64*1024);
260	        if self.budgeted<self.source.len(){self.budgeted=self.budgeted.saturating_add(budget).min(self.source.len());return StreamStatus::Ok}
261	        if !self.parsed {
262	            let cap=self.storage_limit/size_of::<XmlToken>();
263	            let (tokens,result)=tokenize_impl(self.source,&mut XmlLimits{input_bytes:MAX_LARGE_INPUT_BYTES,..XmlLimits::default()},MAX_LARGE_INPUT_BYTES,cap);
264	            if result.diagnostic.category!=XmlError::None{self.result=result;return StreamStatus::Failed}
265	            self.tokens=tokens;self.result=result;self.parsed=true;
266	        }
267	        self.parse_frontier=self.parse_frontier.saturating_add(budget).min(self.source.len());
268	        while self.visible<self.tokens.len() && self.tokens[self.visible].source.end().is_some_and(|end|end<=self.parse_frontier){self.visible+=1}
269	        if self.parse_frontier==self.source.len(){self.finished=true;StreamStatus::Complete}else{StreamStatus::Ok}
270	    }
271	    pub fn result(&self)->XmlResult{self.result}
272	    pub fn bytes_read(&self)->usize{if self.parsed{self.parse_frontier}else if self.source.starts_with(b"\xef\xbb\xbf"){3}else{0}}
273	    pub fn tokens(&self)->&[XmlToken]{&self.tokens[..self.visible]}
274	    pub fn take(&mut self)->Option<Vec<XmlToken>>{if self.finished&&!self.taken{self.taken=true;Some(core::mem::take(&mut self.tokens))}else{None}}
275	    pub fn visitor_storage_bytes(&self)->usize{self.tokens.len().saturating_mul(size_of::<XmlToken>())}
276	    pub fn step_with_visitor<F:FnMut(&XmlToken)->bool>(&mut self,budget:usize,canceled:bool,visitor:&mut F)->StreamStatus{
277	        let status=self.step(budget,canceled); if status==StreamStatus::Failed||status==StreamStatus::Canceled{return status}
278	        while self.visit_index<self.visible {if canceled{self.canceled=true;return StreamStatus::Canceled}if !visitor(&self.tokens[self.visit_index]){self.canceled=true;return StreamStatus::Canceled}self.visit_index+=1}
279	        status
280	    }
281	}
