283	pub fn visit_tokens<F:FnMut(&XmlToken)->bool>(source:&[u8],limits:XmlLimits,visitor:&mut F)->StreamStatus{
284	    let (tokens,result)=tokenize(source,limits);if result.diagnostic.category!=XmlError::None{return StreamStatus::Failed}
285	    for token in &tokens {if !visitor(token){return StreamStatus::Canceled}}StreamStatus::Complete
286	}
