288	pub fn decode_attribute_value(source:&[u8],raw:XmlSpan,output:&mut [u8])->Result<usize,usize>{
289	    let bytes=raw.slice(source).ok_or(0usize)?;let mut p=0;let mut out=0;
290	    while p<bytes.len(){let at=p;if bytes[p]!=b'&'{let Some((cp,end))=utf8_next(bytes,p)else{return Err(at)};if !is_xml_char(cp)||end-p>output.len().saturating_sub(out){return Err(at)}output[out..out+end-p].copy_from_slice(&bytes[p..end]);out+=end-p;p=end;continue}
291	        let semi=bytes[p+1..].iter().take(16).position(|b|*b==b';').map(|v|p+1+v).ok_or(at)?;let body=&bytes[p+1..semi];let cp=match body{b"amp"=>38,b"lt"=>60,b"gt"=>62,b"quot"=>34,b"apos"=>39,_ if body.starts_with(b"#")=>{let (digits,radix)=if body.get(1)==Some(&b'x'){(&body[2..],16)}else{(&body[1..],10)};if digits.is_empty(){return Err(at)}let mut n=0u32;for c in digits{let d=match c{b'0'..=b'9'=>(c-b'0')as u32,b'a'..=b'f'=>(c-b'a'+10)as u32,b'A'..=b'F'=>(c-b'A'+10)as u32,_=>return Err(at)};n=n.checked_mul(radix).and_then(|v|v.checked_add(d)).ok_or(at)?}n},_=>return Err(at)};if !is_xml_char(cp){return Err(at)}let ch=char::from_u32(cp).ok_or(at)?;let mut tmp=[0;4];let enc=ch.encode_utf8(&mut tmp).as_bytes();if enc.len()>output.len().saturating_sub(out){return Err(at)}output[out..out+enc.len()].copy_from_slice(enc);out+=enc.len();p=semi+1;
292	    }Ok(out)
