188	        !add_size(s->result.token_count, 1U, &next)) {
189	        fail(s, SVG_XML_ERROR_OUTPUT_EXHAUSTED, at);
190	        return false;
191	    }
192	    s->tag_tokens[s->tag_token_count++] = token;
193	    s->result.token_count = next;
194	    return true;
195	}
