321	               (byte_at(s,p)>='a'&&byte_at(s,p)<='f') || (byte_at(s,p)>='A'&&byte_at(s,p)<='F')) :
322	               (byte_at(s,p)>='0'&&byte_at(s,p)<='9'))) {
