581	static bool tokenize(xml_scanner *s)
582	{
583	    if(!base_bytes_valid(s->input)||s->tokens==NULL) { fail(s,SVG_XML_ERROR_INVALID_ARGUMENT,0);return false; }
584	    if(s->input.len>s->options.limits.input_bytes) { fail(s,SVG_XML_ERROR_INPUT_LIMIT,s->options.limits.input_bytes);return false; }
585	    if(!scan_chars(s)) return false;
586	    if (starts(s, 0, "\xef\xbb\xbf", 3)) s->cursor = 3;
587	    while(!cancel_requested(s) && s->cursor<s->input.len) {
588	        size_t p=s->cursor;
589	        if(byte_at(s,p)!='<') { if(!parse_text(s))return false; continue; }
590	        if(starts(s,p,"<!--",4)) { if(!parse_comment(s))return false; continue; }
591	        if(starts(s,p,"<?",2)) {
592	            size_t before=s->result.token_count;
593	            if(!parse_pi(s))return false;
594	            if(s->result.token_count>before&&s->tokens[before].kind==SVG_XML_TOKEN_DECLARATION&&
595	               !validate_decl_encoding(s,&s->tokens[before])) return false;
596	            continue;
597	        }
598	        if(starts(s,p,"<![CDATA[",9)) { if(!parse_cdata(s))return false;continue; }
599	        if(starts(s,p,"<!DOCTYPE",9)) { if(!parse_doctype(s))return false;continue; }
600	        if(starts(s,p,"<!ENTITY",8)) { fail(s,SVG_XML_ERROR_UNSUPPORTED_DTD,p);return false; }
601	        if(starts(s,p,"</",2)) { if(!parse_end(s))return false;continue; }
602	        if(starts(s,p,"<!",2)) { fail(s,SVG_XML_ERROR_MALFORMED_SYNTAX,p);return false; }
603	        if(!parse_start(s))return false;
604	        ++s->result.element_count;
605	    }
606	    if(s->depth!=0||s->root_count==0) { fail(s,SVG_XML_ERROR_INCOMPLETE_DOCUMENT,s->input.len);return false; }
607	    return true;
608	}
