610	static bool stream_scan_characters(xml_scanner *s, size_t budget)
611	{
612	    size_t used = 0U;
613	    while (!cancel_requested(s) && used < budget && s->char_cursor < s->input.len) {
614	        uint8_t byte = byte_at(s, s->char_cursor);
615	        if (s->char_pending_length == 0U) {
616	            s->char_sequence_start = s->char_cursor;
617	            s->char_pending_width = byte < 0x80U ? 1U :
618	                (byte >= 0xc2U && byte <= 0xdfU) ? 2U :
619	                (byte >= 0xe0U && byte <= 0xefU) ? 3U :
620	                (byte >= 0xf0U && byte <= 0xf4U) ? 4U : 1U;
621	        }
622	        s->char_pending[s->char_pending_length++] = byte;
623	        ++s->char_cursor;
624	        ++used;
625	        if (s->char_pending_length == s->char_pending_width) {
626	            size_t next = 0U;
627	            uint32_t cp = 0U;
628	            if (!svg_xml_internal_utf8_next(s->char_pending, s->char_pending_length, &next, &cp) ||
629	                next != s->char_pending_length) {
630	                fail(s, SVG_XML_ERROR_INVALID_UTF8, s->char_sequence_start);
631	                return false;
632	            }
633	            if (!svg_xml_internal_char(cp)) {
634	                fail(s, SVG_XML_ERROR_INVALID_CHARACTER, s->char_sequence_start);
635	                return false;
636	            }
637	            s->char_pending_length = 0U;
638	            s->char_pending_width = 0U;
639	        }
640	    }
641	    if (s->char_cursor == s->input.len) {
642	        if (s->char_pending_length != 0U) {
643	            fail(s, SVG_XML_ERROR_INVALID_UTF8, s->char_sequence_start);
644	            return false;
645	        }
646	        s->chars_complete = true;
647	    }
648	    return !s->canceled && s->result.diagnostic.category == SVG_XML_ERROR_NONE;
649	}
