653	static bool stream_parse_next(xml_scanner *s, size_t limit)
654	{
655	    size_t p = s->cursor;
656	    if (s->stream_start_active) return stream_parse_start(s, limit);
657	    if (s->stream_end_active) return stream_parse_end(s, limit);
658	    if (s->pending_kind == XML_STREAM_PENDING_TEXT || byte_at(s, p) != '<')
659	        return stream_parse_text(s, limit);
660	    if (s->pending_kind == XML_STREAM_PENDING_COMMENT || starts(s, p, "<!--", 4U))
661	        return stream_parse_comment(s, limit);
662	    if (s->pending_kind == XML_STREAM_PENDING_PI || starts(s, p, "<?", 2U))
663	        return stream_parse_pi(s, limit);
664	    if (s->pending_kind == XML_STREAM_PENDING_CDATA || starts(s, p, "<![CDATA[", 9U))
665	        return stream_parse_cdata(s, limit);
666	    if (s->pending_kind == XML_STREAM_PENDING_DOCTYPE || starts(s, p, "<!DOCTYPE", 9U))
667	        return stream_parse_doctype(s, limit);
668	    if (starts(s, p, "<!ENTITY", 8U)) {
669	        fail(s, SVG_XML_ERROR_UNSUPPORTED_DTD, p);
670	        return false;
671	    }
672	    if (starts(s, p, "</", 2U)) {
673	        return stream_parse_end(s, limit);
674	    }
675	    if (starts(s, p, "<!", 2U)) {
676	        fail(s, SVG_XML_ERROR_MALFORMED_SYNTAX, p);
677	        return false;
678	    }
679	    return stream_parse_start(s, limit);
680	}
