369	            if (!stream_name(s, &p, limit, &s->stream_attribute_name,
370	                             &s->stream_attribute_prefix, &s->stream_attribute_local_name,
371	                             &name_complete)) return false;
372	            if (!name_complete) break;
373	            if (!valid_qname(s, s->stream_attribute_prefix, s->stream_attribute_local_name)) return false;
374	            size_t attr_begin = s->visitor != NULL ? 1U :
375	                s->stream_start_token_index + 1U;
376	            size_t attr_end = s->visitor != NULL ? s->tag_token_count :
377	                s->result.token_count;
378	            for (size_t i = attr_begin; i < attr_end; ++i) {
379	                const svg_xml_token *prior = s->visitor != NULL ?
380	                    &s->tag_tokens[i] : &s->tokens[i];
381	                if (prior->kind == SVG_XML_TOKEN_ATTRIBUTE &&
382	                    qname_equal(s, s->stream_attribute_name, prior->name)) {
383	                    fail(s, SVG_XML_ERROR_DUPLICATE_ATTRIBUTE, s->stream_start_attribute_offset);
384	                    return false;
385	                }
386	            }
387	            s->stream_start_phase = 1U;
388	        } else if (s->stream_start_phase == 1U) {
389	            while (p < limit && p < s->input.len && svg_xml_internal_whitespace(byte_at(s, p))) ++p;
390	            if (p >= limit && p < s->input.len) break;
391	            if (p >= s->input.len || byte_at(s, p) != '=') { fail(s, SVG_XML_ERROR_MALFORMED_SYNTAX, p); return false; }
392	            ++p;
393	            s->stream_start_phase = 2U;
394	        } else if (s->stream_start_phase == 2U) {
395	            while (p < limit && p < s->input.len && svg_xml_internal_whitespace(byte_at(s, p))) ++p;
396	            if (p >= limit && p < s->input.len) break;
397	            if (p >= s->input.len || (byte_at(s, p) != '\'' && byte_at(s, p) != '"')) {
398	                fail(s, SVG_XML_ERROR_MALFORMED_SYNTAX, p);
399	                return false;
400	            }
401	            s->stream_start_quote = byte_at(s, p++);
402	            s->stream_start_value_offset = p;
403	            s->stream_start_phase = 3U;
404	        } else {
405	            bool paused = false;
406	            while (p < limit && p < s->input.len && byte_at(s, p) != s->stream_start_quote) {
407	                if (byte_at(s, p) == '<') { fail(s, SVG_XML_ERROR_MALFORMED_SYNTAX, p); return false; }
408	                if (byte_at(s, p) == '&') {
409	                    size_t semi = p;
410	                    while (semi < limit && semi < s->input.len && byte_at(s, semi) != ';') ++semi;
411	                    if (semi == limit && semi < s->input.len) { paused = true; break; }
412	                    if (!scan_reference(s, &p)) return false;
413	                } else ++p;
414	            }
415	            if (paused) break;
416	            if (p >= limit && p < s->input.len) break;
417	            if (p >= s->input.len) { fail(s, SVG_XML_ERROR_MALFORMED_SYNTAX, s->stream_start_value_offset - 1U); return false; }
418	            svg_xml_token attribute = {0};
419	            attribute.kind = SVG_XML_TOKEN_ATTRIBUTE;
420	            attribute.name = s->stream_attribute_name;
421	            attribute.prefix = s->stream_attribute_prefix;
422	            attribute.local_name = s->stream_attribute_local_name;
423	            attribute.depth = s->depth;
424	            (void)span_at(s->stream_start_attribute_offset, p + 1U, &attribute.source);
425	            (void)span_at(s->stream_start_value_offset, p, &attribute.value);
426	            if (!stage_tag_token(s, attribute, s->stream_start_attribute_offset)) return false;
427	            ++s->stream_start_local_attributes;
428	            ++s->total_attributes;
429	            ++s->result.attribute_count;
430	            ++p;
431	            s->stream_start_separated = false;
432	            s->stream_start_phase = 0U;
433	        }
434	    }
435	    s->stream_start_pos = p;
515	    return s->result.diagnostic.category == SVG_XML_ERROR_NONE;
516	}
