519	
520	svg_xml_stream_status svg_xml_token_stream_start_visitor(base_bytes input,
521	    svg_xml_token_visitor_fn visitor, void *visitor_context,
522	    svg_xml_cancel_check_fn canceled, void *cancel_context,
523	    svg_xml_token_stream **out_stream)
524	{
525	    if (out_stream == NULL) return SVG_XML_STREAM_FAILED;
526	    *out_stream = NULL;
527	    if (!base_bytes_valid(input) || input.len > 1024U * 1024U * 1024U ||
528	        visitor == NULL) return SVG_XML_STREAM_FAILED;
529	    svg_xml_token_stream *stream = calloc(1U, sizeof(*stream));
530	    if (stream == NULL) return SVG_XML_STREAM_FAILED;
531	    xml_scanner *s = &stream->scanner;
532	    s->tag_token_capacity = XML_MAX_ATTRIBUTES_PER_ELEMENT + 1U;
533	    size_t scratch_bytes = 0U;
534	    if (!base_size_mul(s->tag_token_capacity, sizeof(*s->tag_tokens),
535	                       &scratch_bytes)) {
536	        free(stream);
537	        return SVG_XML_STREAM_FAILED;
538	    }
539	    s->tag_tokens = malloc(scratch_bytes);
540	    if (s->tag_tokens == NULL) {
541	        free(stream);
542	        return SVG_XML_STREAM_FAILED;
543	    }
544	    s->input = input;
545	    s->options = svg_xml_default_options();
546	    s->options.limits.input_bytes = 1024U * 1024U * 1024U;
547	    s->result.diagnostic.category = SVG_XML_ERROR_NONE;
548	    s->visitor = visitor;
549	    s->visitor_context = visitor_context;
550	    s->cancel_check = canceled;
551	    s->cancel_context = cancel_context;
552	    if (starts(s, 0U, "\xef\xbb\xbf", 3U)) s->cursor = 3U;
553	    *out_stream = stream;
554	    return SVG_XML_STREAM_OK;
555	}
