557	size_t svg_xml_token_stream_visitor_storage_bytes(const svg_xml_token_stream *stream)
558	{
559	    if (stream == NULL || stream->scanner.visitor == NULL) return 0U;
560	    return stream->scanner.tag_token_capacity * sizeof(*stream->scanner.tag_tokens);
561	}
