563	bool svg_xml_token_stream_take(svg_xml_token_stream *stream, svg_xml_token **out_tokens,
564	                               size_t *out_token_count)
565	{
566	    if (out_tokens == NULL || out_token_count == NULL) return false;
567	    *out_tokens = NULL;
568	    *out_token_count = 0U;
569	    if (stream == NULL || stream->scanner.visitor != NULL ||
570	        !stream->scanner.stream_complete) return false;
571	    *out_tokens = stream->scanner.tokens;
572	    *out_token_count = stream->scanner.result.token_count;
573	    stream->scanner.tokens = NULL;
574	    stream->scanner.capacity = 0U;
575	    stream->scanner.owns_tokens = false;
576	    return true;
577	}
