 13	static svg_xml_result run(const char *text, svg_xml_options options, svg_xml_token *tokens, size_t cap)
 14	{
 15	    base_bytes input={(const uint8_t *)text,strlen(text)};
 16	    svg_xml_result r=svg_xml_tokenize(input,options,tokens,cap);
 17	    CHECK(r.diagnostic.offset<=input.len);
 18	    if(r.diagnostic.category==SVG_XML_ERROR_NONE) {
 19	        for(size_t i=0;i<r.token_count;++i) {
 20	            CHECK(tokens[i].source.offset<=input.len);
 21	            CHECK(tokens[i].source.length<=input.len-tokens[i].source.offset);
 22	            CHECK(tokens[i].name.offset<=input.len);
 23	            CHECK(tokens[i].name.length<=input.len-tokens[i].name.offset);
 24	            CHECK(tokens[i].value.offset<=input.len);
 25	            CHECK(tokens[i].value.length<=input.len-tokens[i].value.offset);
 26	            CHECK(tokens[i].prefix.offset<=input.len);
 27	            CHECK(tokens[i].prefix.length<=input.len-tokens[i].prefix.offset);
 28	            CHECK(tokens[i].local_name.offset<=input.len);
 29	            CHECK(tokens[i].local_name.length<=input.len-tokens[i].local_name.offset);
 30	        }
 31	    } else CHECK(r.token_count==0);
 32	    return r;
 33	}
