 52	static void check_doctype(void)
 53	{
 54	    svg_xml_token tokens[64];
 55	    static const char *const accepted[] = {
 56	        "<!DOCTYPE a><a/>",
 57	        "<!DOCTYPE svg PUBLIC \"-//W3C//DTD SVG 1.1//EN\"\n \"http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd\"><a/>",
 58	        "<!DOCTYPE svg [\n<!ENTITY ns \"http://www.w3.org/2000/svg\">\n]><a/>",
 59	        "<!DOCTYPE svg [<!-- ]> \">\" --><!ENTITY e \"a>b]\"><?pi ]> ?>]><a/>",
 60	        "<?xml version='1.0'?>\n<!DOCTYPE svg [<!ELEMENT a ANY>]>\n<a/>"};
 61	    for(size_t i=0;i<sizeof(accepted)/sizeof(accepted[0]);++i) {
 62	        svg_xml_result r=run(accepted[i],svg_xml_default_options(),tokens,64);
 63	        CHECK(r.diagnostic.category==SVG_XML_ERROR_NONE);
 64	        size_t found=SIZE_MAX;
 65	        for(size_t k=0;k<r.token_count;++k)if(tokens[k].kind==SVG_XML_TOKEN_DOCTYPE)found=k;
 66	        CHECK(found!=SIZE_MAX);
 67	        const char *end=strstr(accepted[i],"<a/>");
 68	        CHECK(end!=NULL);
 69	        size_t start=(size_t)(strstr(accepted[i],"<!DOCTYPE")-accepted[i]);
 70	        size_t stop=(size_t)(end-accepted[i]);
 71	        while(accepted[i][stop-1]=='\n')--stop;
 72	        CHECK(tokens[found].source.offset==start&&tokens[found].source.length==stop-start);
 73	        CHECK(r.element_count==1);
 74	    }
 75	    /* A declared entity is skipped, never expanded: its reference still fails. */
 76	    expect_error("<!DOCTYPE a [<!ENTITY e \"x\">]><a>&e;</a>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 77	    expect_error("<!DOCTYPE a [<!ENTITY e \"x\">]><a v='&e;'/>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 78	    expect_error("<!DOCTYPE a><a/><!DOCTYPE b>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 79	    expect_error("<a/><!DOCTYPE a>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 80	    expect_error("<a><!DOCTYPE a></a>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 81	    expect_error("<!DOCTYPE a><!DOCTYPE a><a/>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 82	    expect_error("<!DOCTYPEa><a/>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 83	    expect_error("<!DOCTYPE a [<!ENTITY e \"x\"><a/>",SVG_XML_ERROR_MALFORMED_SYNTAX);
 84	    expect_error("<!DOCTYPE a",SVG_XML_ERROR_MALFORMED_SYNTAX);
 85	    expect_error("<!ENTITY e \"x\"><a/>",SVG_XML_ERROR_UNSUPPORTED_DTD);
 86	}
