 88	static void check_attribute_decoder(void)
 89	{
 90	    static const uint8_t source[] = "a&amp;&#65;&#x1f600;z";
 91	    uint8_t output[32] = {0};
 92	    size_t length = 0U, error = SIZE_MAX;
 93	    CHECK(svg_xml_decode_attribute_value((base_bytes){source, sizeof(source) - 1U},
 94	        (svg_xml_span){0U, sizeof(source) - 1U}, output, sizeof(output),
 95	        &length, &error));
 96	    static const uint8_t expected[] = "a&A\xf0\x9f\x98\x80z";
 97	    CHECK(length == sizeof(expected) - 1U &&
 98	          memcmp(output, expected, sizeof(expected) - 1U) == 0);
 99	    static const uint8_t named[] = "&lt;&gt;&quot;&apos;&amp;";
100	    CHECK(svg_xml_decode_attribute_value((base_bytes){named, sizeof(named) - 1U},
101	        (svg_xml_span){0U, sizeof(named) - 1U}, output, sizeof(output),
102	        &length, &error));
103	    static const uint8_t named_expected[] = "<>\"'&";
104	    CHECK(length == sizeof(named_expected) - 1U &&
105	          memcmp(output, named_expected, sizeof(named_expected) - 1U) == 0);
106	    static const char *const invalid[] = {
107	        "&unknown;", "&#;", "&#x;", "&#1114112;", "&#x110000;",
108	        "&#xD800;", "&#0;", "&amp", "&#999999999999999999;"
109	    };
110	    for (size_t i = 0U; i < sizeof(invalid) / sizeof(invalid[0]); ++i) {
111	        base_bytes input = {(const uint8_t *)invalid[i], strlen(invalid[i])};
112	        CHECK(!svg_xml_decode_attribute_value(input,
113	            (svg_xml_span){0U, input.len}, output, sizeof(output),
114	            &length, &error));
115	        CHECK(error == 0U);
116	    }
117	    static const uint8_t too_small[] = "&#x1f600;";
118	    CHECK(!svg_xml_decode_attribute_value((base_bytes){too_small,
119	        sizeof(too_small) - 1U}, (svg_xml_span){0U, sizeof(too_small) - 1U},
120	        output, 3U, &length, &error));
121	    CHECK(error == 0U);
122	    static const uint8_t prefixed[] = "xx&bad;";
123	    CHECK(!svg_xml_decode_attribute_value((base_bytes){prefixed,
124	        sizeof(prefixed) - 1U}, (svg_xml_span){2U, sizeof(prefixed) - 3U},
125	        output, sizeof(output), &length, &error));
126	    CHECK(error == 0U);
127	}
