 32	bool svg_xml_decode_attribute_value(base_bytes input, svg_xml_span raw,
 33	    uint8_t *output, size_t output_capacity, size_t *output_length,
 34	    size_t *error_offset)
 35	{
 36	    if (output_length == NULL || error_offset == NULL || !base_bytes_valid(input) ||
 37	        raw.offset > input.len || raw.length > input.len - raw.offset ||
 38	        (output == NULL && output_capacity != 0U)) return false;
 39	    *output_length = 0U;
 40	    *error_offset = 0U;
 41	    size_t cursor = 0U;
 42	    while (cursor < raw.length) {
 43	        if (input.ptr[raw.offset + cursor] != '&') {
 44	            uint32_t cp = 0U;
 45	            size_t next = raw.offset + cursor;
 46	            if (!svg_xml_internal_utf8_next(input.ptr, raw.offset + raw.length,
 47	                                             &next, &cp) ||
 48	                !svg_xml_internal_char(cp)) {
 49	                *error_offset = cursor;
 50	                return false;
 51	            }
 52	            size_t width = next - (raw.offset + cursor);
 53	            if (width > output_capacity - *output_length) {
 54	                *error_offset = cursor;
 55	                return false;
 56	            }
 57	            memcpy(output + *output_length, input.ptr + raw.offset + cursor, width);
 58	            *output_length += width;
 59	            cursor += width;
 60	            continue;
 61	        }
 62	        size_t start = cursor;
 63	        size_t semicolon = start + 1U;
 64	        while (semicolon < raw.length && semicolon - start <= 16U &&
 65	               input.ptr[raw.offset + semicolon] != ';') ++semicolon;
 66	        if (semicolon >= raw.length || semicolon - start > 16U ||
 67	            input.ptr[raw.offset + semicolon] != ';') {
 68	            *error_offset = start;
 69	            return false;
 70	        }
 71	        size_t body = start + 1U;
 72	        size_t body_length = semicolon - body;
 73	        const uint8_t *value = input.ptr + raw.offset + body;
 74	        uint32_t cp = 0U;
 75	        if (body_length == 3U && memcmp(value, "amp", 3U) == 0) cp = '&';
 76	        else if (body_length == 2U && memcmp(value, "lt", 2U) == 0) cp = '<';
 77	        else if (body_length == 2U && memcmp(value, "gt", 2U) == 0) cp = '>';
 78	        else if (body_length == 4U && memcmp(value, "quot", 4U) == 0) cp = '"';
 79	        else if (body_length == 4U && memcmp(value, "apos", 4U) == 0) cp = '\'';
 80	        else if (body_length >= 2U && value[0] == '#') {
 81	            size_t digit = 1U;
 82	            unsigned radix = 10U;
 83	            if (digit < body_length && (value[digit] == 'x' || value[digit] == 'X')) {
 84	                ++digit;
 85	                radix = 16U;
 86	            }
 87	            if (digit == body_length) { *error_offset = start; return false; }
 88	            for (; digit < body_length; ++digit) {
 89	                uint8_t c = value[digit];
 90	                unsigned n;
 91	                if (c >= '0' && c <= '9') n = (unsigned)(c - '0');
 92	                else if (radix == 16U && c >= 'a' && c <= 'f') n = (unsigned)(c - 'a') + 10U;
 93	                else if (radix == 16U && c >= 'A' && c <= 'F') n = (unsigned)(c - 'A') + 10U;
 94	                else { *error_offset = start; return false; }
 95	                if (cp > (0x10ffffU - n) / radix) { *error_offset = start; return false; }
 96	                cp = cp * radix + n;
 97	            }
 98	        } else { *error_offset = start; return false; }
 99	        if (!svg_xml_internal_char(cp) ||
100	            !decode_append(cp, output, output_capacity, output_length)) {
101	            *error_offset = start;
102	            return false;
103	        }
104	        cursor = semicolon + 1U;
105	    }
106	    return true;
107	}
